// Check what slicer-parse-relevant keywords exist in our recovery gcode.
import fs from "node:fs";

const REC = "<EXPORT_ROOT>/recovery-remainder-starter.gcode";
const txt = fs.readFileSync(REC, "utf8");

const keys = [
  ";TIME",
  ";FILAMENT_USED",
  ";LAYER_COUNT",
  ";filament used",
  "; estimated printing time",
  ";Printer name",
  ";Printer model",
  ";Filament used",
  ";Filament type",
  ";Layer height",
  "; MINX",
  "; MINY",
  "; MINZ",
  "; MAXX",
  "; MAXY",
  "; MAXZ",
  ";TYPE:",
  "M73 P",
  "SET_PRESSURE_ADVANCE",
  "G92",
  ";Generated with",
  "; generated by",
  "; total layer number",
  "; max_z_height",
  ";HEIGHT:",
  ";Z:",
  "; layer_height",
  "; smooth_spiral",
  ";filament_settings_id",
  ";printer_settings_id",
  ";printer_model",
  ";nozzle_diameter",
  ";filament_type",
];
for (const k of keys) {
  const n = (txt.split(k) ?? []).length - 1;
  if (n > 0) console.log(String(n).padStart(5), JSON.stringify(k));
}
